    userName: '林恩典',
    userAvatar: 'https://picsum.photos/100/100?random=u2',
    isOnline: true,
    role: 'M.Div 2022'
  },
  {
    id: 'c3',
    userId: 'u3',
    userName: '李保罗 博士',
    userAvatar: 'https://ui-avatars.com/api/?name=Paul+Lee&background=1e3a8a&color=fff',
    isOnline: false,
    role: 'Professor'
  },
  {
    id: 'c4',
    userId: 'u4',
    userName: '张彼得',
    userAvatar: 'https://picsum.photos/100/100?random=u3',
    isOnline: false,
    role: 'B.Th 2024'
  }
];

const INITIAL_MESSAGES: Record<string, Message[]> = {
  'c1': [
    { id: 'm1', text: '同学你好，这里是教务处。', isMe: false, time: '09:40', status: 'read', type: 'text' },
    { id: 'm2', text: '请记得提交下学期的选课申请表，截止日期是本周五。', isMe: false, time: '09:45', status: 'read', type: 'text' }
  ],
  'c2': [
    { id: 'm1', text: '最近怎么样？听说你家里有些事情。', isMe: true, time: '昨天 14:20', status: 'read', type: 'text' },
    { id: 'm2', text: '是啊，不过现在好多了。', isMe: false, time: '昨天 14:30', status: 'read', type: 'text' },
    { id: 'm3', text: '谢谢你的代祷！事情已经顺利解决了。', isMe: false, time: '昨天 14:31', status: 'read', type: 'text' }
  ]
};

const COMMON_EMOJIS = ["😀", "😂", "🥰", "😍", "🙏", "👍", "❤️", "🎉", "🔥", "🤔", "😭", "🙌", "👋", "💪", "✝️", "🕊️"];

interface ChatViewProps {
  onBack: () => void;
  initialChatId?: string | null;
}

const ChatView: React.FC<ChatViewProps> = ({ onBack, initialChatId }) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(INITIAL_MESSAGES);
  const [inputText, setInputText] = useState("");
  const [showPlusMenu, setShowPlusMenu] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  // Voice Recording State
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const recordingTimerRef = useRef<number | null>(null);

  // Audio Playback State
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);

  // Refs
  const imageInputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const activeConv = INITIAL_CONVERSATIONS.find(c => c.id === activeChatId) || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];

  useEffect(() => {
    if (initialChatId) setActiveChatId(initialChatId);
  }, [initialChatId]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [currentMessages, activeChatId, showPlusMenu, showEmojiPicker, isRecording]);

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', hour12: false}),
      status: 'sent',
      type: 'text',
      ...msgData
    };

    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setShowPlusMenu(false); 
    setShowEmojiPicker(false);
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    sendMessage({ text: inputText, type: 'text' });
    setInputText("");
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const imageUrl = URL.createObjectURL(file);
      sendMessage({ type: 'image', content: imageUrl });
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const size = file.size < 1024 * 1024 
        ? `${(file.size / 1024).toFixed(1)} KB`
        : `${(file.size / (1024 * 1024)).toFixed(1)} MB`;

      sendMessage({ 
        type: 'file', 
        content: file.name, 
        meta: size 
      });
    }
  };

  const handleSendLocation = () => {
    sendMessage({ 
      type: 'location', 
      text: 'AMAS 亚洲宣教神学院', 
      content: '香港九龙塘多实街12号' 
    });
  };

  const handleSendVideo = () => {
    sendMessage({ 
      type: 'video', 
      content: 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?auto=format&fit=crop&w=1000&q=80',
      meta: '02:14' 
    });
  };

  // --- Voice Recording Logic ---
  const startRecording = () => {
    setIsRecording(true);
    setRecordingDuration(0);
    recordingTimerRef.current = window.setInterval(() => {
      setRecordingDuration(prev => prev + 1);
    }, 1000);
  };

  const stopRecording = (send: boolean) => {
    if (recordingTimerRef.current) {
      clearInterval(recordingTimerRef.current);
      recordingTimerRef.current = null;
    }
    setIsRecording(false);

    if (send && recordingDuration > 0) {
      // Mock audio message
      sendMessage({
        type: 'audio',
        meta: formatDuration(recordingDuration),
        content: 'mock_audio_url' 
      });
    }
    setRecordingDuration(0);
  };

  const formatDuration = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  // --- Audio Playback Mock ---
  const toggleAudioPlay = (msgId: string) => {
    if (playingAudioId === msgId) {
      setPlayingAudioId(null);
    } else {
      setPlayingAudioId(msgId);
      // Auto-stop simulation after 3s
      setTimeout(() => {
        setPlayingAudioId(prev => (prev === msgId ? null : prev));
      }, 3000);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] bg-[#F8FAFC] flex flex-col animate-slide-in-right">
       {/* Header */}
       <div className="bg-white pt-safe-top shadow-sm border-b border-slate-200 shrink-0 z-20">
          <div className="px-2 py-2 flex items-center justify-between h-14">
             <div className="flex items-center">
                <button onClick={onBack} className="p-2 -ml-1 rounded-full hover:bg-slate-100 transition text-slate-700">
                   <ChevronLeft size={26} strokeWidth={1.5} />
                </button>
                <div className="flex items-center ml-1 space-x-3">
                   <div className="relative">
                      <div className="w-9 h-9 rounded-full bg-slate-200 border border-slate-100 overflow-hidden">
                        <img src={activeConv.userAvatar} className="w-full h-full object-cover" />
                      </div>
                      {activeConv.isOnline && (
                        <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-emerald-500 border-2 border-white rounded-full"></div>
                      )}
                   </div>
                   <div className="flex flex-col">
                      <h3 className="text-sm font-bold text-slate-900 leading-none mb-0.5">{activeConv.userName}</h3>
                      <p className="text-[10px] text-slate-500">{activeConv.role}</p>
                   </div>
                </div>
             </div>
             <div className="flex items-center space-x-1 text-slate-600">
                <button className="p-2 rounded-full hover:bg-slate-100 transition"><Phone size={22} strokeWidth={1.5} /></button>
                <button className="p-2 rounded-full hover:bg-slate-100 transition"><Video size={24} strokeWidth={1.5} /></button>
                <button className="p-2 rounded-full hover:bg-slate-100 transition"><MoreVertical size={22} strokeWidth={1.5} /></button>
             </div>
          </div>
       </div>

       {/* Messages Area */}
       <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-[#F8FAFC] scrollbar-hide">
          <div className="flex justify-center pt-2">
             <span className="bg-slate-200/50 text-slate-500 text-[10px] px-3 py-1 rounded-full font-medium">
               09:45
             </span>
          </div>

          {currentMessages.map((msg) => (
             <div key={msg.id} className={`flex w-full ${msg.isMe ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
                <div className={`flex max-w-[85%] ${msg.isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                   <div className="shrink-0">
                      {!msg.isMe && (
                         <img src={activeConv.userAvatar} className="w-9 h-9 rounded-full mr-2 border border-white shadow-sm" />
                      )}
                   </div>

                   <div className={`flex flex-col ${msg.isMe ? 'items-end' : 'items-start'}`}>
                      {/* Text Message */}
                      {msg.type === 'text' && (
                         <div className={`px-4 py-2.5 text-[15px] leading-relaxed shadow-sm relative break-words ${
                            msg.isMe 
                              ? 'bg-blue-600 text-white rounded-2xl rounded-tr-sm' 
                              : 'bg-white text-slate-800 rounded-2xl rounded-tl-sm border border-slate-100'
                         }`}>
                            {msg.text}
                         </div>
                      )}

                      {/* Image Message */}
                      {msg.type === 'image' && (
                         <div className="rounded-2xl overflow-hidden shadow-sm border border-slate-200 max-w-[200px]">
                            <img src={msg.content} alt="sent" className="w-full h-auto" />
                         </div>
                      )}

                      {/* Video Message */}
                      {msg.type === 'video' && (
                         <div className="rounded-2xl overflow-hidden shadow-sm border border-slate-200 max-w-[200px] relative">
                            <img src={msg.content} alt="video thumb" className="w-full h-auto opacity-90" />
                            <div className="absolute inset-0 flex items-center justify-center bg-black/20">
                               <div className="w-10 h-10 bg-black/50 rounded-full flex items-center justify-center backdrop-blur-sm">
                                  <PlayCircle size={20} className="text-white ml-0.5" />
                               </div>
                            </div>
                            <div className="absolute bottom-2 right-2 bg-black/60 text-white text-[10px] px-1.5 py-0.5 rounded">
                               {msg.meta}
                            </div>
                         </div>
                      )}

                      {/* Audio Message */}
                      {msg.type === 'audio' && (
                         <div className={`px-3 py-2 rounded-2xl shadow-sm border flex items-center min-w-[140px] ${
                            msg.isMe ? 'bg-blue-600 border-blue-500 text-white' : 'bg-white border-slate-100 text-slate-800'
                         }`}>
                            <button 
                              onClick={() => toggleAudioPlay(msg.id)}
                              className={`w-8 h-8 rounded-full flex items-center justify-center mr-2 shrink-0 ${msg.isMe ? 'bg-white/20' : 'bg-slate-100 text-blue-600'}`}
                            >
                               {playingAudioId === msg.id ? <PauseCircle size={20} /> : <PlayCircle size={20} />}
                            </button>
                            <div className="flex flex-col flex-1 mr-2">
                               <div className="h-1 bg-current opacity-30 rounded-full w-full mb-1 overflow-hidden">
                                  <div className={`h-full bg-current ${playingAudioId === msg.id ? 'w-full transition-all duration-[3000ms] ease-linear' : 'w-0'}`}></div>
                               </div>
                               <span className="text-[10px] opacity-80 font-mono">{msg.meta}</span>
                            </div>
                         </div>
                      )}

                      {/* Location Message */}
                      {msg.type === 'location' && (
                         <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-100 w-[220px]">
                            <div className="h-24 bg-slate-200 relative">
                               <img src="https://images.unsplash.com/photo-1569336415962-a4bd9f69cd83?auto=format&fit=crop&w=600&q=80" className="w-full h-full object-cover opacity-80" />
                               <div className="absolute inset-0 flex items-center justify-center">
                                  <MapPin size={24} className="text-rose-600 drop-shadow-md -mt-2" fill="currentColor" />
                               </div>
                            </div>
                            <div className="p-3">
                               <p className="font-bold text-sm text-slate-900 truncate">{msg.text}</p>
                               <p className="text-xs text-slate-500 truncate">{msg.content}</p>
                            </div>
                         </div>
                      )}

                      {/* File Message */}
                      {msg.type === 'file' && (
                         <div className={`p-3 rounded-2xl shadow-sm border flex items-center w-[220px] ${
                            msg.isMe ? 'bg-blue-600 border-blue-500 text-white' : 'bg-white border-slate-100 text-slate-800'
                         }`}>
                            <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 mr-3 ${
                               msg.isMe ? 'bg-white/20' : 'bg-blue-50 text-blue-600'
                            }`}>
                               <FileText size={20} />
                            </div>
                            <div className="flex-1 min-w-0">
                               <p className="text-sm font-bold truncate">{msg.content}</p>
                               <p className={`text-[10px] ${msg.isMe ? 'text-blue-100' : 'text-slate-400'}`}>{msg.meta}</p>
                            </div>
                         </div>
                      )}

                      <span className={`text-[10px] text-slate-400 mt-1 px-1 ${msg.isMe ? 'text-right' : 'text-left'}`}>
                         {msg.time}
                      </span>
                   </div>
                </div>
             </div>
          ))}
          <div ref={messagesEndRef} />
       </div>

       {/* Input Area */}
       <div className="bg-white border-t border-slate-100 px-4 py-3 pb-safe-area shrink-0 z-20 transition-all duration-300 relative">

          {/* Voice Recording Overlay */}
          {isRecording && (
             <div className="absolute inset-0 bg-white z-30 px-4 flex items-center justify-between animate-fade-in">
                <div className="flex items-center space-x-3 text-rose-500 animate-pulse">
                   <Mic size={24} fill="currentColor" />
                   <span className="font-mono font-bold text-lg">{formatDuration(recordingDuration)}</span>
                </div>
                <div className="flex items-center space-x-4">
                   <button 
                     onClick={() => stopRecording(false)} 
                     className="text-slate-400 font-medium text-sm px-4 py-2 hover:bg-slate-50 rounded-full transition"
                   >
                      取消
                   </button>
                   <button 
                     onClick={() => stopRecording(true)} 
                     className="bg-blue-600 text-white rounded-full p-2 hover:bg-blue-700 transition shadow-md"
                   >
                      <Send size={20} className="ml-0.5" />
                   </button>
                </div>
             </div>
          )}

          <div className="flex items-center space-x-3">
             <button 
                onClick={() => {
                   setShowPlusMenu(!showPlusMenu);
                   setShowEmojiPicker(false);
                }}
                className={`transition-transform duration-300 ${showPlusMenu ? 'rotate-45 text-slate-600' : 'text-slate-400 hover:text-blue-600'}`}
             >
                <Plus size={28} strokeWidth={1.5} />
             </button>

             <div className="flex-1 bg-[#F1F5F9] rounded-2xl flex items-center px-4 py-2.5 transition-colors focus-within:bg-white focus-within:ring-2 focus-within:ring-blue-100">
                <input 
                   value={inputText}
                   onChange={(e) => setInputText(e.target.value)}
                   onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                   type="text" 
                   placeholder="发送消息..."
                   className="flex-1 bg-transparent border-none outline-none text-base text-slate-900 placeholder-slate-400 min-w-0"
                />
                <button 
                  onClick={() => {
                     setShowEmojiPicker(!showEmojiPicker);
                     setShowPlusMenu(false);
                  }}
                  className={`ml-2 transition-colors ${showEmojiPicker ? 'text-amber-500' : 'text-slate-400 hover:text-slate-600'}`}
                >
                   <Smile size={24} strokeWidth={1.5} />
                </button>
             </div>

             {inputText.trim() ? (
                <button onClick={handleSendText} className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-md hover:bg-blue-700 transition active:scale-95">
                   <Send size={20} className="ml-0.5" />
                </button>
             ) : (
                <button 
                  onClick={startRecording}
                  className="w-10 h-10 rounded-full bg-[#F1F5F9] text-slate-500 flex items-center justify-center hover:bg-slate-200 transition active:scale-90"
                >
                   <Mic size={22} strokeWidth={1.5} />
                </button>
             )}
          </div>

          {/* Emoji Picker */}
          {showEmojiPicker && (
             <div className="pt-4 pb-2 animate-slide-up border-t border-slate-50 mt-3">
                <div className="grid grid-cols-8 gap-2">
                   {COMMON_EMOJIS.map((emoji) => (
                      <button 
                        key={emoji}
                        onClick={() => setInputText(prev => prev + emoji)}
                        className="text-2xl hover:bg-slate-100 rounded-lg p-2 transition active:scale-90"
                      >
                         {emoji}
                      </button>
                   ))}
                </div>
             </div>
          )}

          {/* Plus Menu (Expanded functionality) */}
          {showPlusMenu && (
             <div className="grid grid-cols-4 gap-4 pt-6 pb-2 animate-slide-up origin-top">
                {[
                    { icon: Image, label: '相册', color: 'bg-amber-100 text-amber-600', onClick: () => imageInputRef.current?.click() },
                    { icon: Camera, label: '拍摄', color: 'bg-rose-100 text-rose-600', onClick: () => imageInputRef.current?.click() },
                    { icon: Video, label: '视频', color: 'bg-purple-100 text-purple-600', onClick: handleSendVideo },
                    { icon: MapPin, label: '位置', color: 'bg-emerald-100 text-emerald-600', onClick: handleSendLocation },
                    { icon: FileText, label: '文件', color: 'bg-blue-100 text-blue-600', onClick: () => fileInputRef.current?.click() },
                ].map((item, i) => (
                    <button 
                      key={i} 
                      onClick={item.onClick}
                      className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition active:scale-95"
                    >
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${item.color} shadow-sm`}>
                            <item.icon size={26} strokeWidth={1.5} />
                        </div>
                        <span className="text-xs text-slate-500">{item.label}</span>
                    </button>
                ))}
             </div>
          )}

          {/* Hidden Inputs */}
          <input 
            type="file" 
            ref={imageInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleImageSelect}
          />
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            onChange={handleFileSelect}
          />
       </div>
    </div>
  );
};

export default ChatView;
